<body>
<header>
  <h1>My Bookmarks</h1>
  <p>Your one place to save and find links.</p>
</header>
<main>
  <form class="saver" id="saver" autocomplete="off">
    <input type="url" id="urlInput" placeholder="Paste a link here…  e.g. https://en.wikipedia.org/wiki/Bookmark" required />
    <button type="submit">Save</button>
  </form>

  <div class="flash" id="flash"></div>
  <p class="count" id="count"></p>
  <ul class="list" id="list"></ul>
</main>

<div class="overlay" id="overlay">
  <div class="modal">
    <div class="head" id="modalHead">Review &amp; save</div>
    <div class="loading" id="loadingBox">
      <div class="spinner"></div>
      <div>Fetching page details…</div>
    </div>
    <div class="pad" id="formBox" style="display:none">
      <div class="previewImg" id="mPreview"></div>
      <div class="fieldLabel"><span class="fav" id="mFav"></span> Title</div>
      <input type="text" id="mTitle" />
      <div class="fieldLabel">Description</div>
      <textarea id="mDesc"></textarea>
      <div class="urlLine" id="mUrl"></div>
    </div>
    <div class="foot" id="footBox" style="display:none">
      <button class="btn-ghost" id="mCancel">Cancel</button>
      <button class="btn-primary" id="mSave">Save bookmark</button>
    </div>
  </div>
</div>

<script>
  var STORE = "bm_proto_v2";
  function load() { try { return JSON.parse(localStorage.getItem(STORE)) || []; } catch (e) { return []; } }
  function persist(items) { localStorage.setItem(STORE, JSON.stringify(items)); }

  function normalize(url) {
    var u = url.trim().toLowerCase();
    u = u.replace(/^https?:\/\//, "").replace(/^www\./, "").replace(/\/+$/, "");
    return u;
  }

  var PALETTE = ["#2f6feb","#e0447a","#16a34a","#d97706","#7c3aed","#0891b2","#dc2626","#4f46e5"];
  function colorFor(host) { var s = 0; for (var i=0;i<host.length;i++) s += host.charCodeAt(i); return PALETTE[s % PALETTE.length]; }

  function svgPreview(label, color) {
    var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="600" height="360">' +
      '<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">' +
      '<stop offset="0" stop-color="' + color + '"/>' +
      '<stop offset="1" stop-color="#111827"/></linearGradient></defs>' +
      '<rect width="600" height="360" fill="url(#g)"/>' +
      '<text x="30" y="330" font-family="sans-serif" font-size="26" fill="rgba(255,255,255,.9)">' + label + '</text>' +
      '<text x="30" y="70" font-family="sans-serif" font-size="20" fill="rgba(255,255,255,.5)">preview</text>' +
      '</svg>';
    return "url('data:image/svg+xml;utf8," + encodeURIComponent(svg) + "')";
  }

  // Simulated metadata retrieval. Pre-loaded details for a few example sites,
  // with a sensible fallback so any pasted link demonstrates the flow.
  var CATALOG = {
    "en.wikipedia.org": { site: "Wikipedia", desc: "Free encyclopedia article. In-depth background, history, and references on the topic." },
    "github.com":       { site: "GitHub",    desc: "Source code repository with README, issues, and release notes for the project." },
    "www.youtube.com":  { site: "YouTube",   desc: "Online video. Watch, save to playlists, and pick up where you left off." },
    "youtube.com":      { site: "YouTube",   desc: "Online video. Watch, save to playlists, and pick up where you left off." },
    "www.nytimes.com":  { site: "The New York Times", desc: "News article with reporting and analysis from The New York Times." },
    "medium.com":       { site: "Medium",    desc: "Long-form article and personal essay published on Medium." },
    "developer.mozilla.org": { site: "MDN Web Docs", desc: "Reference documentation and guides for web platform technologies." }
  };
  function titleize(seg) {
    seg = decodeURIComponent(seg).replace(/\.[a-z0-9]+$/i, "").replace(/[-_]+/g, " ").trim();
    return seg.split(" ").map(function (w) { return w ? w.charAt(0).toUpperCase() + w.slice(1) : w; }).join(" ");
  }
  function fakeFetch(url) {
    var host, path = "";
    try { var u = new URL(url); host = u.hostname; path = u.pathname; }
    catch (e) { host = url.replace(/^https?:\/\//, "").split("/")[0]; }
    var bareHost = host.replace(/^www\./, "");
    var cat = CATALOG[host] || CATALOG[bareHost];
    var site = cat ? cat.site : (bareHost.split(".")[0].charAt(0).toUpperCase() + bareHost.split(".")[0].slice(1));
    var seg = path.split("/").filter(Boolean).pop();
    var topic = seg ? titleize(seg) : site + " home";
    var title = seg ? (topic + " — " + site) : (site + " — home page");
    var desc = cat ? cat.desc.replace("the topic", topic) : ("A page on " + bareHost + " about " + topic + ".");
    var color = colorFor(bareHost);
    return {
      title: title,
      description: desc,
      icon: { letter: site.charAt(0).toUpperCase(), color: color },
      preview: { label: site, color: color }
    };
  }

  // ---- rendering ----
  function render(highlightId) {
    var items = load();
    var list = document.getElementById("list");
    var count = document.getElementById("count");
    list.innerHTML = "";
    if (items.length === 0) {
      count.textContent = "";
      list.innerHTML = '<div class="empty"><div class="big">🔖</div>Nothing saved yet. Paste a link above and press Save.</div>';
      return;
    }
    count.textContent = items.length + (items.length === 1 ? " saved link" : " saved links");
    items.forEach(function (it) {
      var li = document.createElement("li");
      li.className = "item" + (it.id === highlightId ? " flash-existing" : "");
      li.innerHTML =
        '<div class="thumb"></div>' +
        '<div class="body">' +
          '<a class="open" href="' + it.url + '" target="_blank" rel="noopener">' +
            '<div class="titleRow"><span class="fav"></span><span class="title"></span></div>' +
            '<p class="desc"></p>' +
            '<div class="url"></div>' +
          '</a>' +
          '<div class="actions"><button data-edit="' + it.id + '">Edit</button></div>' +
        '</div>';
      li.querySelector(".thumb").style.backgroundImage = svgPreview(it.preview.label, it.preview.color);
      var fav = li.querySelector(".fav");
      fav.textContent = it.icon.letter; fav.style.background = it.icon.color;
      li.querySelector(".title").textContent = it.title;
      li.querySelector(".desc").textContent = it.description;
      li.querySelector(".url").textContent = it.url;
      list.appendChild(li);
    });
    list.querySelectorAll("button[data-edit]").forEach(function (b) {
      b.addEventListener("click", function () {
        var id = b.getAttribute("data-edit");
        var item = load().filter(function (x) { return x.id === id; })[0];
        if (item) openEditExisting(item);
      });
    });
  }

  function flash(msg, kind) {
    var f = document.getElementById("flash");
    f.className = "flash " + (kind || "ok");
    f.textContent = msg;
    f.style.display = "block";
    clearTimeout(f._t);
    f._t = setTimeout(function () { f.style.display = "none"; }, 3200);
  }

  // ---- modal / editor ----
  var overlay = document.getElementById("overlay");
  var editState = { mode: null, id: null, url: null, meta: null };

  function showModal() { overlay.classList.add("show"); }
  function hideModal() { overlay.classList.remove("show"); }
  function showLoading() {
    document.getElementById("modalHead").textContent = "Review & save";
    document.getElementById("loadingBox").style.display = "block";
    document.getElementById("formBox").style.display = "none";
    document.getElementById("footBox").style.display = "none";
    showModal();
  }
  function fillForm(headText, meta, url) {
    document.getElementById("modalHead").textContent = headText;
    document.getElementById("loadingBox").style.display = "none";
    document.getElementById("formBox").style.display = "block";
    document.getElementById("footBox").style.display = "flex";
    document.getElementById("mPreview").style.backgroundImage = svgPreview(meta.preview.label, meta.preview.color);
    var fav = document.getElementById("mFav");
    fav.textContent = meta.icon.letter; fav.style.background = meta.icon.color;
    document.getElementById("mTitle").value = meta.title;
    document.getElementById("mDesc").value = meta.description;
    document.getElementById("mUrl").textContent = url;
  }

  function openAddFlow(url) {
    showLoading();
    setTimeout(function () {
      var meta = fakeFetch(url);
      editState = { mode: "new", id: null, url: url, meta: meta };
      fillForm("Review & save", meta, url);
      document.getElementById("mTitle").focus();
    }, 650);
  }

  function openEditExisting(item) {
    editState = { mode: "edit", id: item.id, url: item.url,
      meta: { title: item.title, description: item.description, icon: item.icon, preview: item.preview } };
    fillForm("Edit bookmark", editState.meta, item.url);
    showModal();
  }

  document.getElementById("mCancel").addEventListener("click", hideModal);
  overlay.addEventListener("click", function (e) { if (e.target === overlay) hideModal(); });

  document.getElementById("mSave").addEventListener("click", function () {
    var title = document.getElementById("mTitle").value.trim();
    var desc = document.getElementById("mDesc").value.trim();
    var items = load();
    if (editState.mode === "new") {
      items.unshift({
        id: "b" + Date.now(),
        url: editState.url,
        norm: normalize(editState.url),
        title: title || editState.meta.title,
        description: desc,
        icon: editState.meta.icon,
        preview: editState.meta.preview,
        savedAt: Date.now()
      });
      persist(items);
      hideModal();
      render();
      flash("Saved “" + (title || editState.meta.title) + "”.", "ok");
    } else {
      for (var i = 0; i < items.length; i++) {
        if (items[i].id === editState.id) { items[i].title = title || items[i].title; items[i].description = desc; }
      }
      persist(items);
      hideModal();
      render(editState.id);
      flash("Changes saved.", "ok");
    }
  });

  document.getElementById("saver").addEventListener("submit", function (e) {
    e.preventDefault();
    var input = document.getElementById("urlInput");
    var url = input.value.trim();
    if (!url) return;
    var norm = normalize(url);
    var existing = load().filter(function (x) { return x.norm === norm; })[0];
    if (existing) {
      input.value = "";
      flash("You already saved this link — opening it so you can edit.", "info");
      render(existing.id);
      openEditExisting(existing);
      var el = document.querySelector(".flash-existing");
      if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
      return;
    }
    input.value = "";
    openAddFlow(url);
  });

  render();
  document.body.setAttribute("data-harness-ready", "true");
</script>
</body>
</html>
